using System.Text;
using Mutagen.Bethesda.Plugins;
using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Plugins.Records;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Component fields from the round-4 unknown-field evidence pass:
// - C123: BodyPartInfoComponent GNAM is a link to BodyPartData (a FormID kept as raw bytes, never remapped). Its only
//   value in Starfield.esm, on SimpleGroup_CHARGEN_Cheeks1, is HumanBodyPartData (003481:Starfield.esm).
// - CityMapsUsageComponent MOD2 is xEdit's Model Path, a 260-byte zero-padded string (4 CELL in SFBGS008.esm).
// - A volume's four VolumesMatrix rows are a 4x4 transform: column W is 0, 0, 0, 1 in all 18,884 volumes of
//   Starfield.esm and the last row holds the translation. Rows are Row0-2 and Translation, columns X, Y, Z, W.
// Real records are read whole with both readers and written back byte for byte (the City Maps component, which only
// CELLs of SFBGS008.esm carry, is read inside a minimal record and its MOD2 compared).
public class ComponentR6Tests
{
    private static byte[] Content(Action<Mutagen.Bethesda.Plugins.Binary.Streams.MutagenWriter> write)
        => GameConstants.Starfield.MajorRecord(Write(write)).Content.ToArray();

    // SimpleGroup_CHARGEN_Cheeks1 (01F91C:Starfield.esm)
    private const string Cheeks = "";

    // VOL_REF_Int_Nishina_B_X_X_X_27 (13C557:Starfield.esm)
    private const string VolumeStatic = "";

    // [no EditorID] (20255D:Starfield.esm), a reference with 5 volumes
    private const string VolumeRef = "";

    // MOD2 of CELL 0F4ED4:SFBGS008.esm: "CityMaps\SFBGS008\SFBGS008_CityMaps_NewAtlantisTheWell.nif", zero-padded to 260
    private const string CityMapPath = "";

    [Fact]
    public void BodyPartInfo_BodyPartDataLink()
    {
        foreach (var avmd in ReadBoth<IActorValueModulationGetter>(Record("AVMD", Hex(Cheeks)), f => ActorValueModulation.CreateFromBinary(f), (s, p) => ActorValueModulationBinaryOverlay.ActorValueModulationFactory(s, p)))
        {
            var comp = avmd.Components.OfType<IBodyPartInfoComponentGetter>().Single();
            // HumanBodyPartData (003481:Starfield.esm)
            comp.BodyPartData.FormKey.ID.ShouldBe(0x003481u);
            avmd.EnumerateFormLinks().Select(l => l.FormKey.ID).ShouldContain(0x003481u);
            Content(w => avmd.WriteToBinary(w)).ShouldBe(Hex(Cheeks));
        }
    }

    [Fact]
    public void CityMapsUsage_ModelPath()
    {
        var mod2 = Hex(CityMapPath);
        var bytes = Record("GBFM",
            Subrecord("EDID", Encoding.ASCII.GetBytes("CityMapTest\0")),
            Subrecord("BFCB", Encoding.ASCII.GetBytes("BGSCityMapsUsage_Component\0")),
            Subrecord("MOD2", mod2),
            Subrecord("BFCE", Array.Empty<byte>()));
        foreach (var gbfm in ReadBoth<IGenericBaseFormGetter>(bytes, f => GenericBaseForm.CreateFromBinary(f), (s, p) => GenericBaseFormBinaryOverlay.GenericBaseFormFactory(s, p)))
        {
            var comp = gbfm.Components.OfType<ICityMapsUsageComponentGetter>().Single();
            comp.ModelPath.ShouldBe(@"CityMaps\SFBGS008\SFBGS008_CityMaps_NewAtlantisTheWell.nif");
            var written = GameConstants.Starfield.MajorRecord(Write(w => gbfm.WriteToBinary(w)));
            written.TryFindSubrecord(new RecordType("MOD2"))!.Value.Content.ToArray().ShouldBe(mod2);
        }
    }

    [Fact]
    public void Volumes_TransformRows()
    {
        foreach (var stat in ReadBoth<IStaticGetter>(Record("STAT", Hex(VolumeStatic)), f => Static.CreateFromBinary(f), (s, p) => StaticBinaryOverlay.StaticFactory(s, p)))
        {
            var item = stat.Components.OfType<IVolumesComponentGetter>().Single().Items.Single();
            item.Row0.ShouldNotBeNull().X.ShouldBe(1f);
            item.Row1.ShouldNotBeNull().Y.ShouldBe(1f);
            item.Row2.ShouldNotBeNull().Z.ShouldBe(1f);
            var t = item.Translation.ShouldNotBeNull();
            (t.X, t.Y, t.Z, t.W).ShouldBe((0f, 0f, 0f, 1f));
            Content(w => stat.WriteToBinary(w)).ShouldBe(Hex(VolumeStatic));
        }
        foreach (var refr in ReadBoth<IPlacedObjectGetter>(Record("REFR", Hex(VolumeRef)), f => PlacedObject.CreateFromBinary(f), (s, p) => PlacedObjectBinaryOverlay.PlacedObjectFactory(s, p)))
        {
            var items = refr.Components.OfType<IVolumesComponentGetter>().Single().Items;
            items.Count.ShouldBe(5);
            items.ShouldAllBe(i => i.Row0!.W == 0 && i.Row1!.W == 0 && i.Row2!.W == 0 && i.Translation!.W == 1);
            var t = items[0].Translation!;
            t.X.ShouldBe(0.1663f, 0.0001f);
            t.Y.ShouldBe(3.9898f, 0.0001f);
            t.Z.ShouldBe(0.8789f, 0.0001f);
            Content(w => refr.WriteToBinary(w)).ShouldBe(Hex(VolumeRef));
        }
    }
}
